/// <reference path="../pb_data/types.d.ts" />

// User-facing auth + booking request workflow:
// - users: built-in auth collection, registration only via invite token (users.pb.js route)
// - invites: single-use registration tokens generated by admins, valid for 24 hours
// - bookings.status: pending | approved | rejected (rejected slots are free again)
// - bookings.user: requester relation (empty for admin-created bookings)
migrate(
  (app) => {
    const users = app.findCollectionByNameOrId("users");
    users.listRule = '@request.auth.collectionName = "admins"';
    users.viewRule = '@request.auth.collectionName = "admins" || id = @request.auth.id';
    // Registration bypasses the API and goes through /api/hall-logger/register.
    users.createRule = null;
    users.updateRule = '@request.auth.collectionName = "admins" || id = @request.auth.id';
    users.deleteRule = '@request.auth.collectionName = "admins"';
    if (!users.fields.getByName("name")) {
      users.fields.add(new TextField({ name: "name", required: true, max: 100 }));
    } else {
      users.fields.getByName("name").required = true;
    }
    app.save(users);

    const invites = new Collection({
      type: "base",
      name: "invites",
      listRule: '@request.auth.collectionName = "admins"',
      viewRule: '@request.auth.collectionName = "admins"',
      createRule: '@request.auth.collectionName = "admins"',
      updateRule: '@request.auth.collectionName = "admins"',
      deleteRule: '@request.auth.collectionName = "admins"',
      fields: [
        { name: "token", type: "text", required: true, min: 16, max: 64 },
        { name: "expiresAt", type: "date", required: true },
        {
          name: "usedBy",
          type: "relation",
          collectionId: users.id,
          maxSelect: 1,
          cascadeDelete: false,
        },
        { name: "usedAt", type: "date" },
      ],
      indexes: ["CREATE UNIQUE INDEX idx_invites_token ON invites (token)"],
    });
    app.save(invites);

    const bookings = app.findCollectionByNameOrId("bookings");
    bookings.fields.add(
      new SelectField({
        name: "status",
        required: false,
        maxSelect: 1,
        values: ["pending", "approved", "rejected"],
      })
    );
    bookings.fields.add(
      new RelationField({
        name: "user",
        collectionId: users.id,
        maxSelect: 1,
        cascadeDelete: false,
      })
    );
    bookings.createRule =
      '@request.auth.collectionName = "admins" || (@request.auth.collectionName = "users" && user = @request.auth.id && status = "pending")';
    bookings.updateRule = '@request.auth.collectionName = "admins"';
    bookings.deleteRule =
      '@request.auth.collectionName = "admins" || (@request.auth.collectionName = "users" && user = @request.auth.id && status = "pending")';
    app.save(bookings);

    // Existing bookings were created by admins and stay usable.
    for (const record of app.findAllRecords("bookings")) {
      record.set("status", "approved");
      app.save(record);
    }

    const statusField = bookings.fields.getByName("status");
    statusField.required = true;
    app.save(bookings);
  },
  (app) => {
    const invites = app.findCollectionByNameOrId("invites");
    app.delete(invites);

    const bookings = app.findCollectionByNameOrId("bookings");
    bookings.createRule = '@request.auth.collectionName = "admins"';
    bookings.updateRule = '@request.auth.collectionName = "admins"';
    bookings.deleteRule = '@request.auth.collectionName = "admins"';
    for (const name of ["status", "user"]) {
      const field = bookings.fields.getByName(name);
      if (field) bookings.fields.removeById(field.id);
    }
    app.save(bookings);

    const users = app.findCollectionByNameOrId("users");
    users.listRule = "id = @request.auth.id";
    users.viewRule = "id = @request.auth.id";
    users.createRule = "";
    users.updateRule = "id = @request.auth.id";
    users.deleteRule = "id = @request.auth.id";
    const nameField = users.fields.getByName("name");
    if (nameField) nameField.required = false;
    app.save(users);
  }
);
